using ApiFromLecture.Binders;using ApiFromLecture.Models;using Microsoft.AspNetCore.Mvc; namespace ApiFromLecture.Controllers; [ApiController][Route("api/products")] public class ProductsController:ControllerBase{static readonly List<Product> P=new(){new(){Id=1,Name="Ноутбук",Price=75000,CategoryId=1},new(){Id=2,Name="Телефон",Price=50000,CategoryId=1},new(){Id=3,Name="Наушники",Price=5000,CategoryId=2}}; [HttpGet("{id:int}")]public IActionResult Get(int id){var p=P.FirstOrDefault(x=>x.Id==id);return p is null?Problem(title:"Product not found",detail:$"Product with id {id} does not exist",statusCode=404,type:"https://example.com/errors/not-found"):Ok(p);} [HttpGet("by-ids")]public IActionResult ByIds([ModelBinder(typeof(CsvIntArrayBinder))]int[] ids)=>Ok(P.Where(x=>ids.Contains(x.Id))); [HttpPost]public IActionResult Create(CreateProductRequest r){var p=new Product{Id=P.Count==0?1:P.Max(x=>x.Id)+1,Name=r.Name,Price=r.Price,CategoryId=r.CategoryId};P.Add(p);return CreatedAtAction(nameof(Get),new{id=p.Id},p);} [HttpPost("binding/{categoryId:int}")]public IActionResult Binding([FromRoute]int categoryId,[FromQuery]bool notify,[FromBody]CreateProductRequest request,[FromHeader(Name="X-Request-Id")]string? requestId)=>Ok(new{categoryId,notify,request,requestId}); [HttpPost("user")]public IActionResult User(UserDto user)=>Ok(user);}
